      en: ["Dedicated to the politician Amdi Bajram (1951–2020)", "Located in the center of the Šuto Orizari municipality", "Amdi Bajram was a long-serving member of the parliament", "Named 'Amdi Pasha' as a sign of local reverence and respect", "Symbolizes the political struggle for Roma rights and recognition", "Erected to commemorate his contribution to local self-governance"],
