      pt: ["Dedicado ao político Amdi Bajram (1951-2020)", "Localizado no centro do município de Šuto Orizari", "Amdi Bajram foi deputado parlamentar durante muitos anos", "Recebe o nome de 'Amdi Pasha' como expressão de veneração local", "Símbolo da luta política pelos direitos dos ciganos", "Erguido como monumento pelo seu contributo para a autonomia local"],
