    type: "landmark",
    parent: "MK-046",
    coords: [21.4331, 41.9961],
    name: { de: "Mazedonien-Platz", hu: "Macedónia tér", ro: "Piața Macedonia", en: "Maceodnia Square" },
    description: {
      de: "Der Hauptplatz von Skopje, dominiert von der monumentalen Statue 'Krieger auf dem Pferd'.",
      hu: "Szkopje főtere, amelyet a monumentális 'Harcos lovon' szobor ural.",
      ro: "Piața principală din Skopje, dominată de statuia monumentală 'Războinic pe cal'.",
      en: "The main square of Skopje, dominated by the monumental 'Warrior on a Horse' statue.",
      es: "La plaza principal de Skopie, dominada por la monumental estatua 'Guerrero a caballo'.",
      pt: "A praça principal de Escópia, dominada pela estátua monumental 'Guerreiro a Cavalo'.",
      fr: "La place principale de Skopje, dominée par la statue monumentale 'Guerrier à cheval'.",
    },
    descriptionAdvanced: {
      de: "Der Mazedonien-Platz ist der zentrale Platz von Skopje und das Herzstück des sozialen und politischen Lebens der Hauptstadt. Mit einer Fläche von etwa 18.500 Quadratmetern ist er der größte Platz des Landes und Schauplatz zahlreicher historischer Ereignisse, darunter die Proklamation der Unabhängigkeit Mazedoniens im Jahr 1991. Im Rahmen des Projekts 'Skopje 2014' wurde der Platz umfassend umgestaltet und mit zahlreichen Denkmälern und monumentalen Gebäuden geschmückt. Das markanteste Merkmal ist das 22 Meter hohe Denkmal 'Krieger auf dem Pferd', das Alexander den Großen darstellt und in einem prächtigen Brunnen steht. Um den Platz herum befinden sich wichtige Institutionen, Hotels und Einkaufszentren, die ihn zu einem beliebten Treffpunkt für Einwohner und Touristen machen. Die Fußgängerzone verbindet den Platz direkt mit der historischen Steinbrücke, die über den Fluss Vardar führt. Regelmäßige Veranstaltungen, Märkte und öffentliche Feierlichkeiten finden hier das ganze Jahr über statt.",
      hu: "A Macedónia tér Szkopje központi tere, a főváros társadalmi és politikai életének szíve. Mintegy 18 500 négyzetméteres területével az ország legnagyobb tere, számos történelmi esemény helyszíne, többek között itt kiáltották ki Macedónia függetlenségét 1911-ben. A 'Skopje 2014' projekt keretében a teret jelentősen átalakították, számos emlékművel és monumentális épülettel gazdagítva. Legmeghatározóbb eleme a 22 méter magas 'Harcos lovon' emlékmű, amely Nagy Sándort ábrázolja egy pompás szökőkút közepén. A tér körül fontos intézmények, szállodák és bevásárlóközpontok találhatók, így a helyiek és a turisták kedvelt találkozóhelye. A gyalogos zóna közvetlenül összeköti a teret a Vardar folyón átívelő történelmi Kőhíddal. Egész évben rendszeres rendezvényeknek, piacoknak és nyilvános ünnepségeknek ad otthont.",
      ro: "Piața Macedonia este piața centrală din Skopje și nucleul vieții sociale și politice a capitalei. Cu o suprafață de aproximativ 18.500 de metri pătrați, este cea mai mare piață din țară și locul multor evenimente istorice, inclusiv proclamarea independenței Macedoniei în 1991. Ca parte a proiectului 'Skopje 2014', piața a fost remodelată extensiv, fiind decorată cu numeroase monumente și clădiri monumentale. Caracteristica sa cea mai proeminentă este monumentul 'Războinic pe cal', înalt de 22 de metri, care îl înfățișează pe Alexandru cel Mare în centrul unei fântâni magnifice. În jurul pieței se află instituții importante, hoteluri și centre comerciale, transformând-o într-un punct de întâlnire popular pentru locuitori și turiști. Zona pietonală conectează piața direct de Podul de Piatră istoric, care traversează râul Vardar. Evenimente regulate, piețe și sărbători publice au loc aici pe parcursul întregului an.",
      en: "Macedonia Square is the central square of Skopje and the heart of the capital's social and political life. Covering an area of approximately 18,500 square meters, it is the largest square in the country and the site of many historical events, including the proclamation of Macedonia's independence in 1991. As part of the 'Skopje 2014' project, the square was extensively remodeled and decorated with numerous monuments and monumental buildings. Its most prominent feature is the 22-meter-high 'Warrior on a Horse' monument, depicting Alexander the Great, situated within a grand fountain. Surrounding the square are important institutions, hotels, and shopping centers, making it a popular meeting point for locals and tourists alike. The pedestrian zone connects the square directly to the historic Stone Bridge crossing the Vardar River. Regular events, markets, and public celebrations take place here throughout the year.",
      es: "La Plaza de Macedonia es la plaza central de Skopie y la pieza central de la vida social y política de la capital. Con una superficie de unos 18.500 metros cuadrados, es la plaza más grande del país y escenario de numerosos eventos históricos, incluida la proclamación de la independencia de Macedonia en 1991. En el marco del proyecto 'Skopje 2014', la plaza fue remodelada íntegramente y adornada con numerosos monumentos y edificios monumentales. El rasgo más distintivo es el monumento de 22 metros de altura 'Guerrero a caballo', que representa a Alejandro Magno y se alza en una magnífica fuente. Alrededor de la plaza se encuentran importantes instituciones, hoteles y centros comerciales que la convierten en un lugar de encuentro popular para residentes y turistas. La zona peatonal conecta la plaza directamente con el histórico Puente de Piedra que cruza el río Vardar. Eventos regulares, mercados y celebraciones públicas tienen lugar aquí durante todo el año.",
      pt: "A Praça da Macedónia é a praça central de Escópia e o coração da vida social e política da capital. Com uma área de cerca de 18.500 metros quadrados, é a maior praça do país e palco de inúmeros eventos históricos, incluindo a proclamação da independência da Macedónia em 1991. No âmbito do projeto 'Skopje 2014', a praça foi profundamente remodelada e adornada com inúmeros monumentos e edifícios monumentais. A característica mais marcante é o monumento de 22 metros de altura 'Guerreiro a Cavalo', que representa Alexandre, o Grande, e se encontra numa fonte magnífica. Em redor da praça situam-se importantes instituições, hotéis e centros comerciais, que a tornam um ponto de encontro popular para residentes e turistas. A zona pedonal liga a praça diretamente à histórica Ponte de Pedra, que atravessa o rio Vardar. Eventos regulares, mercados e celebrações públicas ocorrem aqui durante todo o ano.",
      fr: "La place de Macédoine est la place centrale de Skopje et le cœur de la vie sociale et politique de la capitale. Avec une superficie d'environ 18 500 mètres carrés, c'est la plus grande place du pays et le théâtre de nombreux événements historiques, dont la proclamation de l'indépendance de la Macédoine en 1991. Dans le cadre du projet 'Skopje 2014', la place a été entièrement réaménagée et ornée de nombreux monuments et bâtiments monumentaux. L'élément le plus marquant est le monument de 22 mètres de haut 'Guerrier à cheval', représentant Alexandre le Grand et trônant au centre d'une fontaine magnifique. Autour de la place se trouvent d'importantes institutions, des hôtels et des centres commerciaux, ce qui en fait un lieu de rencontre prisé des habitants et des touristes. La zone piétonne relie directement la place au pont de pierre historique qui enjambe le fleuve Vardar. Des événements réguliers, des marchés et des célébrations publiques s'y déroulent tout au long de l'année.",
    },
