      ro: ["Cea mai mare piață din Macedonia de Nord, cu 18.500 m².", "Locul declarației de independență din 8 septembrie 1991.", "Monumentul lui Alexandru are o înălțime de 22 de metri.", "Punct central al proiectului de revitalizare 'Skopje 2014'.", "Conectată direct cu Podul de Piatră peste râul Vardar.", "Găzduiește Porta Macedonia, un arc de triumf."],
      en: ["Largest square in North Macedonia at 18,500 m².", "Site of the independence declaration on September 8, 1991.", "The Alexander monument stands 22 meters tall in total.", "Central focus of the 'Skopje 2014' revitalization project.", "Directly connected to the Stone Bridge over the Vardar.", "Home to the Porta Macedonia, a triumphal arch."],
      es: ["Plaza más grande de Macedonia del Norte con 18.500 m²", "Lugar de la declaración de independencia el 8 de septiembre de 1991", "El monumento a Alejandro mide 22 metros de altura", "Punto central del proyecto de revitalización 'Skopje 2014'", "Conectada directamente con el Puente de Piedra sobre el Vardar", "Alberga la Puerta Macedonia, un arco de triunfo"],
      pt: ["A maior praça da Macedónia do Norte com 18.500 m²", "Local da declaração de independência a 8 de setembro de 1991", "O monumento a Alexandre tem 22 metros de altura", "Ponto central do projeto de revitalização 'Skopje 2014'", "Ligada diretamente à Ponte de Pedra sobre o Vardar", "Abriga a Porta Macedónia, um arco do triunfo"],
      fr: ["Plus grande place de Macédoine du Nord avec 18 500 m²", "Lieu de la déclaration d'indépendance le 8 septembre 1991", "Le monument d'Alexandre mesure 22 mètres de haut", "Point central du projet de revitalisation 'Skopje 2014'", "Directement reliée au pont de pierre sur le Vardar", "Abrite la Porte Macédoine, un arc de triomphe"],
