    coords: [21.4167, 41.4167],
    name: { de: "Dorf Dolneni", hu: "Dolneni falu", ro: "Satul Dolneni", en: "Dolneni Village" },
    description: {
      de: "Das Verwaltungszentrum der Gemeinde, bekannt für seine landwirtschaftliche Tradition.",
      hu: "A község közigazgatási központja, mezőgazdasági hagyományairól ismert.",
      ro: "Centrul administrativ al municipalității, cunoscut pentru tradiția sa agricolă.",
      en: "The administrative center of the municipality, known for its agricultural tradition.",
      es: "El centro administrativo del municipio, conocido por su tradición agrícola.",
      pt: "O centro administrativo do município, conhecido pela sua tradição agrícola.",
      fr: "Le centre administratif de la municipalité, connu pour sa tradition agricole.",
    },
    descriptionAdvanced: {
      de: "Das Dorf Dolneni ist das Verwaltungszentrum der gleichnamigen Gemeinde und ein bedeutender kultureller Knotenpunkt in der Region Pelagonien. Es ist weit über die Landesgrenzen hinaus bekannt für seine tiefe Verbundenheit mit der mazedonischen Volksmusik und traditionellen Instrumenten. Jährlich findet hier das Pece-Atanasovski-Festival statt, das Dudelsackspieler und Musiker aus dem ganzen Land anzieht, um das Erbe der authentischen Folklore zu bewahren. Die Umgebung von Dolneni ist geprägt von fruchtbarem Ackerland und bedeutenden Marmorvorkommen, die für die lokale Wirtschaft von großer Bedeutung sind. Historisch gesehen war die Region ein wichtiger Teil der mittelalterlichen mazedonischen Geschichte, was durch zahlreiche archäologische Fundstätten und alte Kirchen in der Nähe belegt wird. Das Dorf bewahrt eine traditionelle Lebensweise, in der Landwirtschaft und Handwerk eine zentrale Rolle spielen. Besucher schätzen die Gastfreundschaft der Bewohner und die Möglichkeit, die unverfälschte ländliche Kultur Mazedoniens hautnah zu erleben.",
      hu: "Dolneni falu az azonos nevű község közigazgatási központja és a Pelagóniai régió jelentős kulturális csomópontja. Az országhatárokon túl is ismert a macedón népzenéhez és a hagyományos hangszerekhez fűződő mély kapcsolatáról. Itt rendezik meg évente a Pece Atanaszovszki Fesztivált, amely dudásokat és zenészeket vonz az egész országból, hogy megőrizzék a hiteles folklór örökségét. Dolneni környékét termékeny mezőgazdasági földek és jelentős márványlelőhelyek jellemzik, amelyek nagy fontossággal bírnak a helyi gazdaság számára. Történelmi szempontból a régió a középkori macedón történelem fontos része volt, amit a közelben található számos régészeti lelőhely és régi templom is bizonyít. A falu őrzi a hagyományos életmódot, amelyben a mezőgazdaság és a kézművesség központi szerepet játszik. A látogatók nagyra értékelik a lakók vendégszeretetét és a lehetőséget, hogy közelebbről megismerjék Macedónia hamisítatlan vidéki kultúráját.",
      ro: "Satul Dolneni este centrul administrativ al comunei cu același nume și un nod cultural important în regiunea Pelagonia. Este cunoscut dincolo de granițele țării pentru legătura sa profundă cu muzica populară macedoneană și instrumentele tradiționale. Anual, aici are loc Festivalul Pece Atanasovski, care atrage cimpoieri și muzicieni din întreaga țară pentru a păstra moștenirea folclorului autentic. Împrejurimile localității Dolneni sunt caracterizate de terenuri agricole fertile și zăcăminte semnificative de marmură, care sunt de mare importanță pentru economia locală. Din punct de vedere istoric, regiunea a fost o parte importantă a istoriei macedonene medievale, fapt atestat de numeroasele situri arheologice și biserici vechi din apropiere. Satul păstrează un mod de viață tradițional, în care agricultura și meșteșugurile joacă un rol central. Vizitatorii apreciază ospitalitatea locuitorilor și posibilitatea de a experimenta cultura rurală autentică a Macedoniei.",
      en: "Dolneni Village serves as the administrative center of the municipality and is a significant cultural hub in the Pelagonia region. It is widely known for its deep connection to Macedonian folk music and traditional instruments. Every year, the village hosts the Pece Atanasovski Festival, which attracts bagpipe players and musicians from all over the country to preserve the heritage of authentic folklore. The surroundings of Dolneni are characterized by fertile agricultural land and significant marble deposits, which are of great importance to the local economy. Historically, the region was an important part of medieval Macedonian history, evidenced by numerous archaeological sites and old churches in the vicinity. The village maintains a traditional lifestyle where agriculture and crafts play a central role. Visitors appreciate the hospitality of the residents and the opportunity to experience the genuine rural culture of Macedonia firsthand.",
      es: "El pueblo de Dolneni es el centro administrativo del municipio homónimo y un importante nodo cultural en la región de Pelagonia. Es conocido mucho más allá de las fronteras nacionales por su profunda conexión con la música folclórica macedonia y los instrumentos tradicionales. Cada año se celebra aquí el Festival Pece Atanasovski, que atrae a gaiteros y músicos de todo el país para preservar el patrimonio del folclore auténtico. El entorno de Dolneni se caracteriza por tierras de cultivo fértiles e importantes yacimientos de mármol, fundamentales para la economía local. Históricamente, la región fue una parte importante de la historia medieval macedonia, como lo demuestran numerosos yacimientos arqueológicos y antiguas iglesias cercanas. El pueblo conserva un estilo de vida tradicional donde la agricultura y la artesanía desempeñan un papel central. Los visitantes aprecian la hospitalidad de los habitantes y la oportunidad de experimentar de cerca la auténtica cultura rural de Macedonia.",
      pt: "A aldeia de Dolneni é o centro administrativo do município com o mesmo nome e um importante nó cultural na região de Pelagônia. É conhecida muito para além das fronteiras nacionais pela sua profunda ligação à música folclórica macedónia e aos instrumentos tradicionais. Anualmente, realiza-se aqui o Festival Pece Atanasovski, que atrai gaiteiros e músicos de todo o país para preservar a herança do folclore autêntico. Os arredores de Dolneni são caracterizados por terras agrícolas férteis e importantes depósitos de mármore, que são de grande importância para a economia local. Historicamente, a região foi uma parte importante da história medieval macedónia, o que é comprovado por numerosos sítios arqueológicos e igrejas antigas nas proximidades. A aldeia preserva um modo de vida tradicional, no qual a agricultura e o artesanato desempenham um papel central. Os visitantes apreciam a hospitalidade dos habitantes e a oportunidade de vivenciar de perto a cultura rural genuína da Macedónia.",
      fr: "Le village de Dolneni est le centre administratif de la municipalité du même nom et un nœud culturel important dans la région de Pélagonie. Il est connu bien au-delà des frontières nationales pour son lien profond avec la musique folklorique macédonienne et les instruments traditionnels. Chaque année s'y déroule le festival Pece Atanasovski, qui attire des joueurs de cornemuse et des musiciens de tout le pays pour préserver l'héritage du folklore authentique. Les environs de Dolneni sont marqués par des terres agricoles fertiles et d'importants gisements de marbre, essentiels pour l'économie locale. Historiquement, la région était une partie importante de l'histoire médiévale macédonienne, comme en témoignent de nombreux sites archéologiques et d'anciennes églises à proximité. Le village conserve un mode de vie traditionnel où l'agriculture et l'artisanat jouent un rôle central. Les visiteurs apprécient l'hospitalité des habitants et la possibilité de découvrir de près la culture rurale authentique de la Macédoine.",
    },
