      hu: ["Dolneni község közigazgatási központja.", "A Pece Atanaszovszki Népi Hangszerfesztivál otthona.", "Híres a hagyományos dudák (gajda) készítéséről.", "A fehér márvány bányászatának fontos helyszíne.", "A Pelagóniai-síkság északi részén fekszik.", "Kiváló minőségű dohánytermeléséről ismert."],
      ro: ["Centrul administrativ al comunei Dolneni.", "Găzduiește Festivalul Pece Atanasovski de instrumente populare.", "Faimos pentru fabricarea cimpoielor tradiționale (gajda).", "Locație importantă pentru extracția marmurei albe.", "Situat în partea de nord a câmpiei Pelagonia.", "Cunoscut pentru producția de tutun de înaltă calitate."],
      en: ["Administrative center of the Dolneni municipality.", "Home to the Pece Atanasovski Festival of Folk Instruments.", "Famous for the production of traditional bagpipes (gajda).", "Important location for the mining of white marble.", "Situated in the northern part of the Pelagonia plain.", "Known for high-quality tobacco production."],
      es: ["Centro administrativo del municipio de Dolneni.", "Sede del Festival Pece Atanasovski de instrumentos folclóricos.", "Famoso por la fabricación de gaitas tradicionales (Gajda).", "Importante lugar de extracción de mármol blanco.", "Ubicado en la parte norte de la llanura de Pelagonia.", "Conocido por la producción de tabaco de alta calidad."],
      pt: ["Centro administrativo do município de Dolneni.", "Sede do Festival Pece Atanasovski de instrumentos folclóricos.", "Famoso pela fabricação de gaitas de foles tradicionais (Gajda).", "Local importante para a extração de mármore branco.", "Localizado na parte norte da planície de Pelagônia.", "Conhecido pela produção de tabaco de alta qualidade."],
      fr: ["Centre administratif de la municipalité de Dolneni.", "Siège du festival Pece Atanasovski pour les instruments folkloriques.", "Célèbre pour la fabrication de cornemuses traditionnelles (Gajda).", "Site important pour l'extraction de marbre blanc.", "Situé dans la partie nord de la plaine de Pélagonie.", "Connu pour la production de tabac de haute qualité."],
